using System;
using System.Linq;
using UnityEngine;
namespace FishSandbox {
 public class GiftPanel:MonoBehaviour {
  public FishingGame game;public bool panel=true;public string category="全部",search="";public GiftDefinition selected;public float duration=15,amount=1;public int count=1;public string target="random";Vector2 scroll,logScroll;bool showHelp;GUIStyle title,label,small,button,bodyStyle,heading,chip,field;Texture2D pixel;Font font;float scale;string lastResult="";
  Color navy=new(.055f,.105f,.14f,.97f),muted=new(.56f,.68f,.7f),white=new(.91f,.94f,.89f),accent=new(1,.68f,.34f),teal=new(.2f,.72f,.65f);
  void Init(){if(title!=null)return;font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei UI","Microsoft YaHei","Arial"},20);pixel=Texture2D.whiteTexture;label=Style(16,white);small=Style(12,muted);title=Style(32,white,FontStyle.Bold);heading=Style(19,white,FontStyle.Bold);bodyStyle=Style(14,white);bodyStyle.wordWrap=true;button=new GUIStyle(GUI.skin.button){font=font,fontSize=15,alignment=TextAnchor.MiddleCenter};button.normal.textColor=white;button.hover.textColor=accent;button.normal.background=Tex(new Color(.12f,.22f,.26f));button.hover.background=Tex(new Color(.18f,.32f,.35f));button.active.background=Tex(new Color(.23f,.4f,.4f));button.border=new RectOffset(0,0,0,0);chip=new GUIStyle(button){fontSize=13};field=new GUIStyle(GUI.skin.textField){font=font,fontSize=14,padding=new RectOffset(10,10,7,5)};field.normal.textColor=white;field.normal.background=Tex(new Color(.035f,.075f,.1f));}
  Texture2D Tex(Color c){var t=new Texture2D(1,1);t.SetPixel(0,0,c);t.Apply();return t;}GUIStyle Style(int size,Color color,FontStyle weight=FontStyle.Normal)=>new(){font=font,fontSize=size,fontStyle=weight,normal=new GUIStyleState{textColor=color},alignment=TextAnchor.MiddleLeft};
  void Fill(Rect r,Color c){var old=GUI.color;GUI.color=c;GUI.DrawTexture(r,pixel);GUI.color=old;}void Text(float x,float y,float w,float h,string s,GUIStyle style=null)=>GUI.Label(new Rect(x,y,w,h),s,style??label);bool Btn(float x,float y,float w,float h,string text)=>GUI.Button(new Rect(x,y,w,h),text,button);
  void OnGUI(){if(game==null||game.gifts==null)return;Init();scale=Mathf.Min(Screen.width/1600f,Screen.height/900f);var old=GUI.matrix;GUI.matrix=Matrix4x4.TRS(new Vector3((Screen.width-1600*scale)/2,(Screen.height-900*scale)/2,0),Quaternion.identity,Vector3.one*scale);
   if(game.gifts.Has("visual/vignette_flash")){var c=new Color(.85f,.22f,.12f,.2f+Mathf.Sin(Time.unscaledTime*5)*.1f);Fill(new Rect(0,0,1600,30),c);Fill(new Rect(0,870,1600,30),c);Fill(new Rect(0,0,30,900),c);Fill(new Rect(1570,0,30,900),c);}if(game.gifts.Has("status/poison"))Fill(new Rect(0,0,1600,12),new Color(.4f,.8f,.2f,.7f));if(game.gifts.Has("status/ignite"))Fill(new Rect(0,888,1600,12),new Color(1,.3f,.1f,.8f));
