   GUI.matrix=old;
  }
  void HUD(){Fill(new Rect(24,22,360,110),navy);Fill(new Rect(24,22,4,110),accent);Text(45,33,330,30,"HOW TO FISH",heading);Text(45,65,330,20,"群岛钓鱼  /  独立重制",small);Text(45,93,330,25,"金币  "+game.coins+"     鱼饵  "+game.bait+"     鱼获  "+game.bag.Count,label);
   Fill(new Rect(24,762,350,112),navy);Text(42,772,300,25,"生命 "+Mathf.CeilToInt(game.health)+"    饱食 "+Mathf.CeilToInt(game.fullness),label);Bar(new Rect(42,806,155,7),game.health/100,new Color(.9f,.43f,.35f));Bar(new Rect(211,806,145,7),game.fullness/100,teal);Text(42,829,310,28,game.driving?"驾驶中 · E 下船":game.tool==0?"1 鱼竿  ·  左键抛竿 / 收线":game.tool==1?"2 步枪  ·  弹药 "+game.ammo+" / 12":"3 手持鱼  ·  左键食用",small);
   if(Time.unscaledTime<game.notifyUntil||game.fishing!=FishingState.Idle){Fill(new Rect(420,772,panel?670:760,88),navy);Text(442,785,panel?625:710,58,game.notification,bodyStyle);}
   if(game.fishing==FishingState.Reeling){Fill(new Rect(430,638,630,102),navy);Text(448,648,590,25,"收线进度 / 鱼线张力（过高时松开左键）",label);Bar(new Rect(448,685,590,12),game.lineProgress,teal);Bar(new Rect(448,711,590,9),game.tension,Color.Lerp(accent,Color.red,game.tension));}
   if(game.fishing==FishingState.Biting){Text(625,400,430,70,"咬钩！点击左键",title);}
   if(!panel&&!game.dead){Fill(new Rect(796,446,8,2),white);Fill(new Rect(799,443,2,8),white);Text(450,865,800,30,"WASD 移动  ·  Space 跳跃  ·  E 交互  ·  1/2/3 切换  ·  F 近战  ·  G 丢出",small);}
   float y=150;foreach(var e in game.gifts.active){Fill(new Rect(24,y,350,33),navy);Text(36,y+2,325,28,e.gift.name+"   "+Mathf.CeilToInt(e.remaining)+"s"+(game.gifts.QueueCount(e.gift.channel)>0?"  +排队 "+game.gifts.QueueCount(e.gift.channel):""),small);y+=37;if(y>650)break;}
   string pending="";if(game.quickBite>0)pending+="瞬咬 ×"+game.quickBite+"  ";if(game.slowBite>0)pending+="慢咬 ×"+game.slowBite+"  ";if(game.nextDrip>0)pending+="潮流 ×"+game.nextDrip+"  ";if(game.nextHeavy>0)pending+="巨重 ×"+game.nextHeavy+"  ";if(game.nextSale>0)pending+="售鱼加成 ×"+game.nextSale+"  ";if(game.lineGuard>0)pending+="护线 ×"+game.lineGuard; if(pending!=""){Fill(new Rect(24,y,350,55),navy);Text(36,y+4,325,47,pending,bodyStyle);}
   if(game.boss&&game.boss.health>0){Fill(new Rect(490,25,560,65),navy);Text(510,31,520,25,"深海首领   "+Mathf.CeilToInt(game.boss.health)+" / "+game.boss.maxHealth,heading);Bar(new Rect(510,68,520,9),game.boss.health/game.boss.maxHealth,new Color(.86f,.3f,.2f));}
  }
  void Bar(Rect r,float p,Color color){Fill(r,new Color(.14f,.23f,.25f));r.width*=Mathf.Clamp01(p);Fill(r,color);}
  void Panel(){Fill(new Rect(1110,0,490,900),navy);Fill(new Rect(1110,0,2,900),new Color(.25f,.42f,.43f));Text(1136,23,360,42,"礼物控制台",title);Text(1138,69,395,24,"本地触发 · "+GiftCatalog.All.Count+" 种效果 · 已触发 "+game.gifts.EventCount+" 次",small);if(Btn(1537,30,40,34,"×"))panel=false;
   search=GUI.TextField(new Rect(1136,106,440,36),search,field);if(search=="")Text(1146,108,420,32,"搜索礼物名称或事件 ID",small);
   var cats=new[]{"全部","钓鱼","增益","整蛊","移动","状态","召唤","船只","战斗","视觉"};for(int i=0;i<cats.Length;i++){var r=new Rect(1136+i%5*89,153+i/5*34,83,28);var old=GUI.backgroundColor;if(category==cats[i])GUI.backgroundColor=teal;if(GUI.Button(r,cats[i],chip)){category=cats[i];scroll=Vector2.zero;}GUI.backgroundColor=old;}
   var list=GiftCatalog.All.Where(x=>(category=="全部"||x.group==category)&&(string.IsNullOrWhiteSpace(search)||x.name.IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0||x.id.IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();
   scroll=GUI.BeginScrollView(new Rect(1136,225,440,279),scroll,new Rect(0,0,416,Mathf.Max(278,list.Length*53)));for(int i=0;i<list.Length;i++){var d=list[i];bool sel=selected==d;Fill(new Rect(0,i*53,416,48),sel?new Color(.18f,.34f,.36f):new Color(.085f,.16f,.19f));if(GUI.Button(new Rect(0,i*53,416,48),"",GUIStyle.none))Select(d);Text(12,i*53+3,390,24,d.name,label);Text(12,i*53+26,390,18,d.id,small);}GUI.EndScrollView();
   if(selected==null)Select(GiftCatalog.All[0]);Text(1136,519,430,27,selected.name,heading);Text(1136,552,440,43,selected.description,bodyStyle);
   if(selected.duration>0){Text(1136,600,120,24,"持续 "+duration.ToString("0")+" 秒",small);duration=GUI.HorizontalSlider(new Rect(1270,608,300,20),duration,1,120);}else{Text(1136,600,120,24,"数量  "+count,small);count=Mathf.RoundToInt(GUI.HorizontalSlider(new Rect(1270,608,300,20),count,1,3));}
   Text(1136,634,150,24,"数值  "+amount.ToString("0.##"),small);GetRange(selected,out float min,out float max);amount=GUI.HorizontalSlider(new Rect(1290,642,280,20),amount,min,max);
   if(selected.id.Contains("spawn")&&selected.id!="chaos/spawn_item"){Text(1136,667,70,28,"鱼种",small);target=GUI.TextField(new Rect(1206,666,363,30),target,field);}else Text(1136,667,430,28,"Tab 隐藏面板后即可自由移动和钓鱼",small);
   var oldColor=GUI.backgroundColor;GUI.backgroundColor=accent;if(Btn(1136,706,282,46,"触发  "+selected.name)){bool ok=game.gifts.Trigger(selected.id,duration,amount,count,target);lastResult=ok?"已触发 · "+selected.name:game.gifts.LastError;}GUI.backgroundColor=oldColor;if(Btn(1427,706,143,46,"恢复全部")){game.gifts.Clear();lastResult="持续与待用效果已全部清除";}Text(1136,756,440,24,lastResult,small);
   var recent=game.gifts.log.Reverse().Take(3).ToArray();for(int i=0;i<recent.Length;i++)Text(1136,786+i*21,440,21,recent[i],small);
   if(Btn(1136,861,210,27,"操作说明"))showHelp=true;if(Btn(1357,861,213,27,"保存进度")){game.Save();lastResult="进度已保存";}
  }
  public void Select(GiftDefinition d){selected=d;duration=d.duration;amount=d.value;count=1;target="random";}
  static void GetRange(GiftDefinition d,out float min,out float max){min=1;max=5;switch(d.id){case "money/add":min=10;max=10000;break;case "money/remove":min=10;max=5000;break;case "player/heal":case "player/feed":max=100;break;case "player/damage":case "player/hunger":max=75;break;case "boss/heal":min=5;max=20;break;case "visual/deep_fog":min=.01f;max=.15f;break;case "chaos/launch":case "chaos/yeet_held_item":case "chaos/boat_boost":min=8;max=38;break;case "movement/slow":case "movement/weak_jump":case "fishing/slow_reel":min=.25f;max=1;break;case "weapon/steady_aim":min=0;max=1;break;case "visual/slow_motion":min=.1f;max=1;break;case "visual/speed_up":min=1;max=3;break;case "chaos/spawn_tiny_fish":min=.2f;max=.5f;break;case "chaos/spawn_giant_fish":min=2;max=5;break;case "bait/refill":max=20;break;case "chaos/dynamite":max=10;break;case "chaos/boat_spin":max=8;break;case "weapon/max_recoil":case "weapon/max_spread":max=8;break;case "fishing/line_guard":min=0;max=1;break;}}
  void Help(){Fill(new Rect(310,145,790,590),navy);Text(345,175,700,50,"从第一条鱼开始",title);string text="1. Tab 关闭礼物面板，鼠标转向，WASD 移动。\n2. 走到码头边，朝海面点击左键抛竿。\n3. 出现咬钩提示时点击提竿，按住左键收线。\n4. 张力快满时松开左键，避免断线。\n5. E 与鱼市交互出售鱼获，靠近营火按 E 烤鱼。\n6. 3 切换手持鱼，左键吃鱼；2 切换步枪，R 补弹。\n7. 靠近小船按 E 驾驶，WASD 开船，E 下船。\n8. 礼物同一通道依次生效，计时使用真实秒数。\n\nSpace 跳跃 · Shift 冲刺 · Ctrl 蹲伏 · F 近战 · G 扔出\n死亡后 Enter 回到码头。存档只属于此独立工程。";Text(345,245,715,390,text,bodyStyle);if(Btn(345,653,250,48,"知道了，开始钓鱼")){showHelp=false;panel=false;}}
 }
